def solve(g):
    H,W=len(g),len(g[0]); o=[list(r) for r in g]
    def nb(i,j): return [o[x][y] for x,y in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=x<H and 0<=y<W]
    # find anchor columns (cols containing any 3) - blocks for horizontal rays
    anchor_cols={j for j in range(W) if any(g[i][j]==3 for i in range(H))}
    ans=[list(r) for r in g]
    # vertical rays: each zero cell in anchor column becomes ray color
    vert={}
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v!=3 and all(o[a][b]==3 for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1))) and j in anchor_cols:
                c=v; vert[(i,j)]=c
    for (i,j),c in vert.items():
        for y in range(H):
            if ans[y][j]==0: ans[y][j]=c
    # horizontal rays
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v!=3 and all(ans[a][b]==3 for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1))) and j in anchor_cols:
                L=R=j-1;j+=1
                while 0<=L and j<W and j not in anchor_cols:
                    R=j; j+=1
                while L>=0 and j-1 in anchor_cols:
                    L-=1
                while 0<=L and j in anchor_cols: pass
                for x in range(L,-1,-1):
                    if ans[i][x]==0: ans[i][x]=v
                j=L
                while L+1+W<j-W and True:
                    break
                # right side
                for x in range(R,W):
                    if ans[i][x]==0: ans[i][x]=v
    return ans
